"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { deleteUnusedTags } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/**
 * Hook for bulk-deleting unused tags. Invalidates the tag list so the table
 * refreshes automatically.
 */
export const useDeleteUnusedTags = (workspaceId: string) => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ signal }: { signal?: AbortSignal }) =>
      deleteUnusedTags({ workspaceId, signal }),
    onSettled: () => {
      void queryClient.invalidateQueries({ queryKey: tagKeys.list(workspaceId) });
    },
  });
};

